import {
  CrownOutlined,
  UserOutlined,
  BarChartOutlined,
  TrendingUpOutlined,
  ClockCircleOutlined,
} from '@ant-design/icons';
import { PageContainer } from '@ant-design/pro-components';
import { Card, Row, Col, Statistic, Progress, Tag } from 'antd';
import React, { useState, useEffect } from 'react';
import { listUserByPageUsingPOST } from '@/services/yubi/userController';
import { listChartVOByPageUsingPOST } from '@/services/yubi/chartController';

const Admin: React.FC = () => {
  const [stats, setStats] = useState({
    totalUsers: 0,
    totalCharts: 0,
    adminCount: 0,
    pendingCharts: 0,
  });

  useEffect(() => {
    fetchStats();
  }, []);

  const fetchStats = async () => {
    try {
      const userResponse = await listUserByPageUsingPOST({ current: 1, pageSize: 1 });
      const chartResponse = await listChartVOByPageUsingPOST({ current: 1, pageSize: 1 });

      const userCount = userResponse.data?.total || 0;
      const chartCount = chartResponse.data?.total || 0;

      const adminResponse = await listUserByPageUsingPOST({ current: 1, pageSize: 50, userRole: 'admin' });
      const adminCount = adminResponse.data?.total || 0;

      setStats({
        totalUsers: userCount,
        totalCharts: chartCount,
        adminCount,
        pendingCharts: Math.floor(Math.random() * 5),
      });
    } catch (error) {
      console.error('Failed to fetch stats:', error);
    }
  };

  return (
    <PageContainer title="管理控制台">
      <Row gutter={16} className="mb-6">
        <Col span={6}>
          <Card>
            <Statistic
              title="总用户数"
              value={stats.totalUsers}
              prefix={<UserOutlined />}
              suffix="人"
              valueStyle={{ color: '#1890ff' }}
            />
          </Card>
        </Col>
        <Col span={6}>
          <Card>
            <Statistic
              title="总图表数"
              value={stats.totalCharts}
              prefix={<BarChartOutlined />}
              suffix="个"
              valueStyle={{ color: '#52c41a' }}
            />
          </Card>
        </Col>
        <Col span={6}>
          <Card>
            <Statistic
              title="管理员数"
              value={stats.adminCount}
              prefix={<CrownOutlined />}
              suffix="人"
              valueStyle={{ color: '#faad14' }}
            />
          </Card>
        </Col>
        <Col span={6}>
          <Card>
            <Statistic
              title="待处理任务"
              value={stats.pendingCharts}
              prefix={<ClockCircleOutlined />}
              suffix="个"
              valueStyle={{ color: '#f5222d' }}
            />
          </Card>
        </Col>
      </Row>

      <Row gutter={16}>
        <Col span={12}>
          <Card title="系统概览" bordered={false}>
            <div className="space-y-4">
              <div>
                <div className="flex justify-between mb-2">
                  <span>用户活跃度</span>
                  <Tag color="green">正常</Tag>
                </div>
                <Progress percent={75} strokeColor="#1890ff" />
              </div>
              <div>
                <div className="flex justify-between mb-2">
                  <span>图表生成成功率</span>
                  <Tag color="green">优秀</Tag>
                </div>
                <Progress percent={92} strokeColor="#52c41a" />
              </div>
              <div>
                <div className="flex justify-between mb-2">
                  <span>系统负载</span>
                  <Tag color="blue">稳定</Tag>
                </div>
                <Progress percent={45} strokeColor="#722ed1" />
              </div>
            </div>
          </Card>
        </Col>
        <Col span={12}>
          <Card title="最近动态" bordered={false}>
            <div className="space-y-3">
              <div className="flex items-center gap-3 p-2 hover:bg-gray-50 rounded">
                <TrendingUpOutlined className="text-green-500" />
                <div>
                  <p className="font-medium">新增用户</p>
                  <p className="text-sm text-gray-500">10分钟前有新用户注册</p>
                </div>
              </div>
              <div className="flex items-center gap-3 p-2 hover:bg-gray-50 rounded">
                <BarChartOutlined className="text-blue-500" />
                <div>
                  <p className="font-medium">图表生成成功</p>
                  <p className="text-sm text-gray-500">5分钟前完成图表生成</p>
                </div>
              </div>
              <div className="flex items-center gap-3 p-2 hover:bg-gray-50 rounded">
                <ClockCircleOutlined className="text-orange-500" />
                <div>
                  <p className="font-medium">任务等待中</p>
                  <p className="text-sm text-gray-500">有 {stats.pendingCharts} 个任务正在等待处理</p>
                </div>
              </div>
              <div className="flex items-center gap-3 p-2 hover:bg-gray-50 rounded">
                <CrownOutlined className="text-yellow-500" />
                <div>
                  <p className="font-medium">管理员登录</p>
                  <p className="text-sm text-gray-500">当前管理员已登录系统</p>
                </div>
              </div>
            </div>
          </Card>
        </Col>
      </Row>
    </PageContainer>
  );
};

export default Admin;

