import {
  UserOutlined,
  EditOutlined,
  BanOutlined,
  UnlockOutlined,
  CrownOutlined,
  UserSwitchOutlined,
  SearchOutlined,
} from '@ant-design/icons';
import { PageContainer } from '@ant-design/pro-components';
import {
  Table,
  Button,
  Input,
  Select,
  Tag,
  Modal,
  Form,
  message,
  Popconfirm,
} from 'antd';
import React, { useState, useEffect } from 'react';
import {
  listUserByPageUsingPOST,
  updateUserUsingPOST,
  deleteUserUsingPOST,
} from '@/services/yubi/userController';

const { Option } = Select;

interface User {
  id: number;
  userAccount: string;
  userName: string;
  userAvatar: string;
  userRole: string;
  phoneNum: string;
  email: string;
  leftCount: number;
  createTime: string;
  updateTime: string;
  isDelete: number;
}

const UserManagement: React.FC = () => {
  const [form] = Form.useForm();
  const [dataSource, setDataSource] = useState<User[]>([]);
  const [pagination, setPagination] = useState({
    current: 1,
    pageSize: 10,
    total: 0,
  });
  const [loading, setLoading] = useState(false);
  const [visible, setVisible] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);

  const fetchUsers = async (params: {
    current?: number;
    pageSize?: number;
    userAccount?: string;
    userName?: string;
    userRole?: string;
  }) => {
    setLoading(true);
    try {
      const response = await listUserByPageUsingPOST({
        current: params.current || 1,
        pageSize: params.pageSize || 10,
        userAccount: params.userAccount,
        userName: params.userName,
        userRole: params.userRole,
      });
      if (response.data) {
        setDataSource(response.data.records || []);
        setPagination({
          current: response.data.current || 1,
          pageSize: response.data.size || 10,
          total: response.data.total || 0,
        });
      }
    } catch (error) {
      message.error('获取用户列表失败');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers({ current: 1, pageSize: 10 });
  }, []);

  const handleSearch = () => {
    const values = form.getFieldsValue();
    fetchUsers({
      current: 1,
      pageSize: pagination.pageSize,
      userAccount: values.userAccount,
      userName: values.userName,
      userRole: values.userRole,
    });
  };

  const handleReset = () => {
    form.resetFields();
    fetchUsers({ current: 1, pageSize: pagination.pageSize });
  };

  const handleTableChange = (page: number, pageSize: number) => {
    const values = form.getFieldsValue();
    fetchUsers({
      current: page,
      pageSize: pageSize,
      userAccount: values.userAccount,
      userName: values.userName,
      userRole: values.userRole,
    });
  };

  const handleEdit = (record: User) => {
    setEditingUser(record);
    setVisible(true);
  };

  const handleSave = async () => {
    if (!editingUser) return;
    try {
      await updateUserUsingPOST({
        id: editingUser.id,
        userRole: editingUser.userRole,
        isDelete: editingUser.isDelete,
      });
      message.success('更新成功');
      setVisible(false);
      fetchUsers({ current: pagination.current, pageSize: pagination.pageSize });
    } catch (error) {
      message.error('更新失败');
    }
  };

  const handleRoleChange = (id: number, role: string) => {
    updateUserUsingPOST({ id, userRole: role })
      .then(() => {
        message.success('角色更新成功');
        fetchUsers({ current: pagination.current, pageSize: pagination.pageSize });
      })
      .catch(() => {
        message.error('角色更新失败');
      });
  };

  const handleStatusChange = (id: number, isDelete: number) => {
    updateUserUsingPOST({ id, isDelete })
      .then(() => {
        message.success(isDelete === 1 ? '用户已禁用' : '用户已启用');
        fetchUsers({ current: pagination.current, pageSize: pagination.pageSize });
      })
      .catch(() => {
        message.error('状态更新失败');
      });
  };

  const handleDelete = (id: number) => {
    deleteUserUsingPOST({ id })
      .then(() => {
        message.success('删除成功');
        fetchUsers({ current: pagination.current, pageSize: pagination.pageSize });
      })
      .catch(() => {
        message.error('删除失败');
      });
  };

  const getRoleTag = (role: string) => {
    const color = role === 'admin' ? 'gold' : role === 'ban' ? 'red' : 'green';
    const text = role === 'admin' ? '管理员' : role === 'ban' ? '已禁用' : '普通用户';
    const icon = role === 'admin' ? (
      <CrownOutlined style={{ marginRight: 4 }} />
    ) : role === 'ban' ? (
      <BanOutlined style={{ marginRight: 4 }} />
    ) : (
      <UserOutlined style={{ marginRight: 4 }} />
    );
    return (
      <Tag color={color}>
        {icon}
        {text}
      </Tag>
    );
  };

  const columns = [
    {
      title: '用户账号',
      dataIndex: 'userAccount',
      key: 'userAccount',
      width: 120,
      ellipsis: true,
    },
    {
      title: '用户昵称',
      dataIndex: 'userName',
      key: 'userName',
      width: 120,
      ellipsis: true,
    },
    {
      title: '角色',
      dataIndex: 'userRole',
      key: 'userRole',
      width: 120,
      render: (role: string) => getRoleTag(role),
    },
    {
      title: '积分',
      dataIndex: 'leftCount',
      key: 'leftCount',
      width: 80,
    },
    {
      title: '邮箱',
      dataIndex: 'email',
      key: 'email',
      width: 180,
      ellipsis: true,
    },
    {
      title: '手机号',
      dataIndex: 'phoneNum',
      key: 'phoneNum',
      width: 120,
    },
    {
      title: '创建时间',
      dataIndex: 'createTime',
      key: 'createTime',
      width: 160,
      render: (time: string) => new Date(time).toLocaleString(),
    },
    {
      title: '操作',
      key: 'actions',
      width: 280,
      render: (_, record: User) => (
        <div className="flex gap-2">
          <Button
            icon={<UserSwitchOutlined />}
            size="small"
            onClick={() => handleRoleChange(record.id, record.userRole === 'admin' ? 'user' : 'admin')}
          >
            {record.userRole === 'admin' ? '设为普通用户' : '设为管理员'}
          </Button>
          <Button
            icon={record.isDelete === 1 ? <UnlockOutlined /> : <BanOutlined />}
            size="small"
            danger={record.isDelete === 0}
            onClick={() => handleStatusChange(record.id, record.isDelete === 1 ? 0 : 1)}
          >
            {record.isDelete === 1 ? '启用' : '禁用'}
          </Button>
          <Button
            icon={<EditOutlined />}
            size="small"
            onClick={() => handleEdit(record)}
          >
            编辑
          </Button>
          <Popconfirm
            title="确定删除该用户？"
            onConfirm={() => handleDelete(record.id)}
          >
            <Button size="small" danger>
              删除
            </Button>
          </Popconfirm>
        </div>
      ),
    },
  ];

  return (
    <PageContainer title="用户管理">
      <Form form={form} layout="inline" className="mb-4">
        <Form.Item label="账号" name="userAccount">
          <Input
            prefix={<SearchOutlined />}
            placeholder="搜索账号"
            style={{ width: 200 }}
          />
        </Form.Item>
        <Form.Item label="昵称" name="userName">
          <Input
            prefix={<SearchOutlined />}
            placeholder="搜索昵称"
            style={{ width: 200 }}
          />
        </Form.Item>
        <Form.Item label="角色" name="userRole">
          <Select placeholder="选择角色" style={{ width: 150 }}>
            <Option value="user">普通用户</Option>
            <Option value="admin">管理员</Option>
            <Option value="ban">已禁用</Option>
          </Select>
        </Form.Item>
        <Form.Item>
          <Button type="primary" onClick={handleSearch}>
            搜索
          </Button>
        </Form.Item>
        <Form.Item>
          <Button onClick={handleReset}>重置</Button>
        </Form.Item>
      </Form>

      <Table
        columns={columns}
        dataSource={dataSource}
        rowKey="id"
        pagination={{
          current: pagination.current,
          pageSize: pagination.pageSize,
          total: pagination.total,
          showSizeChanger: true,
          showQuickJumper: true,
          showTotal: (total) => `共 ${total} 条记录`,
        }}
        loading={loading}
        onChange={(pagination) => handleTableChange(pagination.current!, pagination.pageSize!)}
        scroll={{ x: 1200 }}
      />

      <Modal
        title="编辑用户"
        visible={visible}
        onCancel={() => setVisible(false)}
        onOk={handleSave}
      >
        {editingUser && (
          <Form layout="vertical">
            <Form.Item label="用户账号">
              <Input disabled value={editingUser.userAccount} />
            </Form.Item>
            <Form.Item label="用户昵称">
              <Input disabled value={editingUser.userName} />
            </Form.Item>
            <Form.Item label="角色">
              <Select
                value={editingUser.userRole}
                onChange={(value) => setEditingUser({ ...editingUser, userRole: value })}
              >
                <Option value="user">普通用户</Option>
                <Option value="admin">管理员</Option>
                <Option value="ban">已禁用</Option>
              </Select>
            </Form.Item>
            <Form.Item label="状态">
              <Select
                value={editingUser.isDelete}
                onChange={(value) => setEditingUser({ ...editingUser, isDelete: value })}
              >
                <Option value={0}>启用</Option>
                <Option value={1}>禁用</Option>
              </Select>
            </Form.Item>
          </Form>
        )}
      </Modal>
    </PageContainer>
  );
};

export default UserManagement;

