import {
  BarChartOutlined,
  ClockCircleOutlined,
  LoadingOutlined,
  CheckCircleOutlined,
  CloseCircleOutlined,
  TrashOutlined,
  EyeOutlined,
  SearchOutlined,
} from '@ant-design/icons';
import { PageContainer } from '@ant-design/pro-components';
import {
  Table,
  Button,
  Input,
  Select,
  Tag,
  Modal,
  message,
  Popconfirm,
} from 'antd';
import React, { useState, useEffect } from 'react';
import {
  listChartVOByPageUsingPOST,
  deleteChartUsingPOST,
} from '@/services/yubi/chartController';

const { Option } = Select;

interface Chart {
  id: number;
  goal: string;
  name: string;
  chartType: string;
  Status: number;
  execMessage: string;
  userId: number;
  createTime: string;
  updateTime: string;
}

const ChartManagement: React.FC = () => {
  const [dataSource, setDataSource] = useState<Chart[]>([]);
  const [pagination, setPagination] = useState({
    current: 1,
    pageSize: 10,
    total: 0,
  });
  const [loading, setLoading] = useState(false);
  const [visible, setVisible] = useState(false);
  const [detailChart, setDetailChart] = useState<Chart | null>(null);
  const [searchParams, setSearchParams] = useState({
    goal: '',
    chartType: '',
    status: '',
  });

  const fetchCharts = async (params: {
    current?: number;
    pageSize?: number;
    goal?: string;
    chartType?: string;
    status?: string;
  }) => {
    setLoading(true);
    try {
      const response = await listChartVOByPageUsingPOST({
        current: params.current || 1,
        pageSize: params.pageSize || 10,
        goal: params.goal,
        chartType: params.chartType,
      });
      if (response.data) {
        let records = response.data.records || [];
        if (params.status) {
          records = records.filter((chart: Chart) => String(chart.Status) === params.status);
        }
        setDataSource(records);
        setPagination({
          current: response.data.current || 1,
          pageSize: response.data.size || 10,
          total: response.data.total || 0,
        });
      }
    } catch (error) {
      message.error('获取图表列表失败');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCharts({ current: 1, pageSize: 10 });
  }, []);

  const handleSearch = () => {
    fetchCharts({
      current: 1,
      pageSize: pagination.pageSize,
      ...searchParams,
    });
  };

  const handleReset = () => {
    setSearchParams({ goal: '', chartType: '', status: '' });
    fetchCharts({ current: 1, pageSize: pagination.pageSize });
  };

  const handleTableChange = (page: number, pageSize: number) => {
    fetchCharts({
      current: page,
      pageSize: pageSize,
      ...searchParams,
    });
  };

  const handleViewDetail = (record: Chart) => {
    setDetailChart(record);
    setVisible(true);
  };

  const handleDelete = (id: number) => {
    deleteChartUsingPOST({ id })
      .then(() => {
        message.success('删除成功');
        fetchCharts({ current: pagination.current, pageSize: pagination.pageSize, ...searchParams });
      })
      .catch(() => {
        message.error('删除失败');
      });
  };

  const getStatusTag = (status: number) => {
    const statusMap = {
      0: { color: 'blue', text: '等待生成', icon: <ClockCircleOutlined /> },
      2: { color: 'orange', text: '生成中', icon: <LoadingOutlined spin /> },
      1: { color: 'green', text: '生成成功', icon: <CheckCircleOutlined /> },
      '-1': { color: 'red', text: '生成失败', icon: <CloseCircleOutlined /> },
    };
    const item = statusMap[String(status)] || { color: 'gray', text: '未知', icon: <BarChartOutlined /> };
    return (
      <Tag color={item.color}>
        {item.icon}
        {item.text}
      </Tag>
    );
  };

  const columns = [
    {
      title: '图表名称',
      dataIndex: 'name',
      key: 'name',
      width: 150,
      ellipsis: true,
    },
    {
      title: '分析目标',
      dataIndex: 'goal',
      key: 'goal',
      width: 200,
      ellipsis: true,
    },
    {
      title: '图表类型',
      dataIndex: 'chartType',
      key: 'chartType',
      width: 100,
      ellipsis: true,
    },
    {
      title: '状态',
      dataIndex: 'Status',
      key: 'Status',
      width: 100,
      render: (status: number) => getStatusTag(status),
    },
    {
      title: '用户ID',
      dataIndex: 'userId',
      key: 'userId',
      width: 80,
    },
    {
      title: '创建时间',
      dataIndex: 'createTime',
      key: 'createTime',
      width: 160,
      render: (time: string) => new Date(time).toLocaleString(),
    },
    {
      title: '操作',
      key: 'actions',
      width: 150,
      render: (_, record: Chart) => (
        <div className="flex gap-2">
          <Button
            icon={<EyeOutlined />}
            size="small"
            onClick={() => handleViewDetail(record)}
          >
            详情
          </Button>
          <Popconfirm
            title="确定删除该图表？"
            onConfirm={() => handleDelete(record.id)}
          >
            <Button icon={<TrashOutlined />} size="small" danger>
              删除
            </Button>
          </Popconfirm>
        </div>
      ),
    },
  ];

  return (
    <PageContainer title="图表管理">
      <div className="flex gap-4 mb-4">
        <Input
          prefix={<SearchOutlined />}
          placeholder="搜索分析目标"
          style={{ width: 250 }}
          value={searchParams.goal}
          onChange={(e) => setSearchParams({ ...searchParams, goal: e.target.value })}
        />
        <Select
          placeholder="选择图表类型"
          style={{ width: 150 }}
          value={searchParams.chartType}
          onChange={(value) => setSearchParams({ ...searchParams, chartType: value })}
        >
          <Option value="">全部</Option>
          <Option value="line">折线图</Option>
          <Option value="bar">柱状图</Option>
          <Option value="pie">饼图</Option>
          <Option value="scatter">散点图</Option>
          <Option value="table">表格</Option>
        </Select>
        <Select
          placeholder="选择状态"
          style={{ width: 120 }}
          value={searchParams.status}
          onChange={(value) => setSearchParams({ ...searchParams, status: value })}
        >
          <Option value="">全部</Option>
          <Option value="0">等待生成</Option>
          <Option value="2">生成中</Option>
          <Option value="1">生成成功</Option>
          <Option value="-1">生成失败</Option>
        </Select>
        <Button type="primary" onClick={handleSearch}>
          搜索
        </Button>
        <Button onClick={handleReset}>重置</Button>
      </div>

      <Table
        columns={columns}
        dataSource={dataSource}
        rowKey="id"
        pagination={{
          current: pagination.current,
          pageSize: pagination.pageSize,
          total: pagination.total,
          showSizeChanger: true,
          showQuickJumper: true,
          showTotal: (total) => `共 ${total} 条记录`,
        }}
        loading={loading}
        onChange={(pagination) => handleTableChange(pagination.current!, pagination.pageSize!)}
        scroll={{ x: 1200 }}
      />

      <Modal
        title="图表详情"
        visible={visible}
        onCancel={() => setVisible(false)}
        width={700}
      >
        {detailChart && (
          <div className="space-y-4">
            <div className="flex justify-between items-center">
              <span className="font-bold">图表名称：</span>
              <span>{detailChart.name}</span>
            </div>
            <div className="flex justify-between items-center">
              <span className="font-bold">分析目标：</span>
              <span>{detailChart.goal}</span>
            </div>
            <div className="flex justify-between items-center">
              <span className="font-bold">图表类型：</span>
              <span>{detailChart.chartType}</span>
            </div>
            <div className="flex justify-between items-center">
              <span className="font-bold">状态：</span>
              <span>{getStatusTag(detailChart.Status)}</span>
            </div>
            <div className="flex justify-between items-center">
              <span className="font-bold">用户ID：</span>
              <span>{detailChart.userId}</span>
            </div>
            <div className="flex justify-between items-center">
              <span className="font-bold">创建时间：</span>
              <span>{new Date(detailChart.createTime).toLocaleString()}</span>
            </div>
            <div className="flex justify-between items-center">
              <span className="font-bold">更新时间：</span>
              <span>{new Date(detailChart.updateTime).toLocaleString()}</span>
            </div>
            {detailChart.execMessage && (
              <div>
                <span className="font-bold block mb-2">执行信息：</span>
                <pre className="bg-gray-100 p-4 rounded overflow-auto max-h-40">
                  {detailChart.execMessage}
                </pre>
              </div>
            )}
          </div>
        )}
      </Modal>
    </PageContainer>
  );
};

export default ChartManagement;

